drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · pin the contract options★★☆ core
//  concepts: web defaults · unmapped members · nulls versus defaults · enums as strings · nullable annotations
// ─────────────────────────────────────────────────────────────────────────
//
//  One options object is the wire contract: write it down once, and test it.

using static Bootcamp.Check;
using System.Text.Json;
using System.Text.Json.Serialization;

JsonSerializerOptions ContractOptions() => new(JsonSerializerDefaults.Web)          // camelCase, case-insensitive reads
{
    UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow,                     // a typo or an extra field is an error
    DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,                     // leave out nulls, keep 0 and false
    RespectNullableAnnotations = true,                                                // null for a non-nullable member is an error
    Converters = { new JsonStringEnumConverter(JsonNamingPolicy.CamelCase, allowIntegerValues: false) },
};

// Given: one options instance for every call (each instance builds its own metadata cache).
var contract = new Lazy<JsonSerializerOptions>(ContractOptions);
string Write(OrderDto order) => JsonSerializer.Serialize(order, contract.Value);
OrderDto Read(string json) => JsonSerializer.Deserialize<OrderDto>(json, contract.Value)!;
var placedAt = new DateTimeOffset(2026, 11, 15, 9, 30, 0, TimeSpan.Zero);

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("names are camelCase, a null note is left out, and the status is a camelCase name", () =>
    Eq(Write(new OrderDto { Id = 7, Customer = "ana", Status = OrderStatus.Shipped, Note = null, Total = 12.50m, PlacedAt = placedAt }),
       "{\"id\":7,\"customer\":\"ana\",\"status\":\"shipped\",\"total\":12.50,\"placed_at\":\"2026-11-15T09:30:00+00:00\"}"));

Test("a JsonPropertyName is used as written, both ways", () =>
    Eq(Read("{\"id\":7,\"customer\":\"ana\",\"placed_at\":\"2026-11-15T09:30:00+00:00\"}").PlacedAt, placedAt));

Test("reading ignores the casing of property names", () =>
    Eq(Read("{\"ID\":7,\"Customer\":\"ana\",\"TOTAL\":3.5}"), new OrderDto { Id = 7, Customer = "ana", Total = 3.5m }));

Test("an unknown member is refused instead of silently dropped", () =>
    Throws<JsonException>(() => Read("{\"id\":7,\"customer\":\"ana\",\"isAdmin\":true}")));

Test("a missing required member is refused", () =>
    Throws<JsonException>(() => Read("{\"customer\":\"ana\"}")));

Test("null for a non-nullable member is refused", () =>
    Throws<JsonException>(() => Read("{\"id\":7,\"customer\":null}")));

Test("a status sent as a number is refused, even though it is a valid value", () =>
    Throws<JsonException>(() => Read("{\"id\":7,\"customer\":\"ana\",\"status\":1}")));

Test("zero and the first enum value are still written: only nulls are left out (boundary)", () =>
    Eq(Write(new OrderDto { Id = 0, Customer = "", Status = OrderStatus.Placed, Total = 0m, PlacedAt = placedAt }),
       "{\"id\":0,\"customer\":\"\",\"status\":\"placed\",\"total\":0,\"placed_at\":\"2026-11-15T09:30:00+00:00\"}"));

