drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · polymorphic payment contract★★★ core
//  concepts: entity to DTO · [JsonDerivedType] discriminator · serialize as the base type · out-of-order kind
// ─────────────────────────────────────────────────────────────────────────
//
//  The row stays on the server; the DTO, with its kind, is what the client sees.

using static Bootcamp.Check;
using System.Text.Json;
using System.Text.Json.Serialization;

var paymentJson = new JsonSerializerOptions(JsonSerializerDefaults.Web) { AllowOutOfOrderMetadataProperties = true };

string Mask(string iban) => iban.Length <= 4 ? "****" : "****" + iban[^4..];

PaymentDto ToDto(PaymentEntity entity)
{
    var createdAt = new DateTimeOffset(DateTime.SpecifyKind(entity.CreatedUtc, DateTimeKind.Utc));
    return entity.Kind switch
    {
        "card" => new CardPaymentDto(entity.Id, entity.CardLast4!, createdAt),
        "bank" => new BankPaymentDto(entity.Id, Mask(entity.Iban!), createdAt),
        _ => throw new InvalidOperationException($"payment {entity.Id} has unknown kind '{entity.Kind}'"),
    };
}

// The static type is PaymentDto, so the serializer looks up [JsonDerivedType] and writes "kind" first.
string Serialize(PaymentDto payment) => JsonSerializer.Serialize(payment, paymentJson);

PaymentDto Deserialize(string json) => JsonSerializer.Deserialize<PaymentDto>(json, paymentJson)!;

// Given: two stored rows.
var created = new DateTime(2026, 11, 15, 9, 30, 0, DateTimeKind.Utc);
var cardRow = new PaymentEntity(7, "card", "4242", null, InternalRiskScore: 81, created);
var bankRow = new PaymentEntity(8, "bank", null, "NL91ABNA0417164300", InternalRiskScore: 12, created);

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a card payment is written with its kind first and nothing internal", () =>
    Eq(Serialize(ToDto(cardRow)), "{\"kind\":\"card\",\"id\":7,\"last4\":\"4242\",\"createdAt\":\"2026-11-15T09:30:00+00:00\"}"));

Test("a bank payment shows only the last four characters of the IBAN", () =>
{
    var json = Serialize(ToDto(bankRow));
    Eq(new object[] { json, json.Contains("NL91") }, new object[] { "{\"kind\":\"bank\",\"id\":8,\"maskedIban\":\"****4300\",\"createdAt\":\"2026-11-15T09:30:00+00:00\"}", false });
});

Test("a payment read back is the same derived record", () =>
{
    var card = ToDto(cardRow);
    var back = Deserialize(Serialize(card));
    Eq(new object[] { back.GetType().Name, back }, new object[] { "CardPaymentDto", card });
});

Test("a client may send the kind after the other properties", () =>
    Eq(Deserialize("{\"id\":8,\"maskedIban\":\"****4300\",\"createdAt\":\"2026-11-15T09:30:00+00:00\",\"kind\":\"bank\"}"),
       (PaymentDto)new BankPaymentDto(8, "****4300", new DateTimeOffset(2026, 11, 15, 9, 30, 0, TimeSpan.Zero))));

Test("property names are read whatever their casing", () =>
    Eq(Deserialize("{\"kind\":\"card\",\"ID\":7,\"Last4\":\"4242\",\"CreatedAt\":\"2026-11-15T09:30:00+00:00\"}"), ToDto(cardRow)));

Test("an unknown kind on the wire is refused", () =>
    Throws<JsonException>(() => Deserialize("{\"kind\":\"crypto\",\"id\":9}")));

Test("a stored row of an unknown kind is a bug, not an empty payment", () =>
    Throws<InvalidOperationException>(() => ToDto(cardRow with { Kind = "cash" })));

Test("an IBAN of four characters or fewer is masked entirely (boundary)", () =>
    Eq(((BankPaymentDto)ToDto(bankRow with { Iban = "4300" })).MaskedIban, "****"));

drills.tail:
// ──────────────────────────── types ──────────────────────────────────────

/// <summary>Given: the stored row. It is never serialized.</summary>
sealed record PaymentEntity(int Id, string Kind, string? CardLast4, string? Iban, int InternalRiskScore, DateTime CreatedUtc);

/// <summary>Given: the published contract. The discriminator "kind" names the derived type.</summary>
[JsonPolymorphic(TypeDiscriminatorPropertyName = "kind")]
[JsonDerivedType(typeof(CardPaymentDto), "card")]
[JsonDerivedType(typeof(BankPaymentDto), "bank")]
abstract record PaymentDto;

sealed record CardPaymentDto(int Id, string Last4, DateTimeOffset CreatedAt) : PaymentDto;

sealed record BankPaymentDto(int Id, string MaskedIban, DateTimeOffset CreatedAt) : PaymentDto;

drills.explanation:
Map by kind, then let the serializer see the base type every time:

```csharp
var paymentJson = new JsonSerializerOptions(JsonSerializerDefaults.Web) { AllowOutOfOrderMetadataProperties = true };
PaymentDto ToDto(PaymentEntity e) => e.Kind switch
{
    "card" => new CardPaymentDto(e.Id, e.CardLast4!, createdAt),
    "bank" => new BankPaymentDto(e.Id, Mask(e.Iban!), createdAt),
    _ => throw new InvalidOperationException($"payment {e.Id} has unknown kind '{e.Kind}'"),
};
string Serialize(PaymentDto payment) => JsonSerializer.Serialize(payment, paymentJson);   // T is PaymentDto
```

Serializing with `payment.GetType()` as the type asks for `CardPaymentDto`, so no `kind` is written and "a card payment is written with its kind first and nothing internal" fails, as does the round trip. Leaving out `AllowOutOfOrderMetadataProperties` makes the client that sends `kind` last get a `NotSupportedException`. Returning `null` for an unknown stored kind, instead of throwing, hides a data bug, and copying the IBAN unmasked puts `NL91` into the bank JSON. Dropping the length check in the mask turns `4300` into `****4300` instead of `****`.
